import os, json, re
async def main(args):
    out = []
    cwd = os.getcwd()
    sources = [
        ("local", os.path.join(cwd, ".agent", "skills"), None),
        ("global", os.path.join(os.path.expanduser("~"), ".agt", "skills"), None),
    ]
    act_p = os.path.join(cwd, ".agent", "skills", "global-skills.json")
    act = []
    try:
        if os.path.exists(act_p):
            act = json.load(open(act_p, encoding="utf-8"))
    except Exception:
        act = []
    seen = set()
    for scope, root, allow in sources:
        if not os.path.isdir(root):
            continue
        for name in sorted(os.listdir(root)):
            sk = os.path.join(root, name, "SKILL.md")
            if not os.path.isfile(sk) or name in seen:
                continue
            if allow is not None and scope == "global" and name not in allow:
                continue
            seen.add(name)
            try:
                txt = open(sk, encoding="utf-8", errors="replace").read()
            except Exception:
                continue
            m = re.match(r"^---\s*\n(.*?)\n---", txt, re.S)
            if not m:
                continue
            fm = m.group(1)
            def _g(k, fm=fm):
                mm = re.search("^" + k + r":\s*(.+)$", fm, re.M)
                return mm.group(1).strip().strip("\"'") if mm else ""
            out.append({"name": _g("name") or name,
                        "description": (_g("description") +
                                        ("；适用：" + _g("when_to_use") if _g("when_to_use") else "")).strip("； "),
                        "when": _g("when_to_use")})
    # 封闭集补"无关"候选：jev choice 头必须选一个，不给 other 类任何输入都会被硬塞给某技能
    out.append({"name": "__none__",
                "description": "与以上任何技能都无关的普通对话、闲聊、提问或与本机工具无关的任务",
                "when": ""})
    return {"skills": out, "count": len(out)}

import json
async def main(args):
    p = args.params
    skills = p.get("skills") or []
    if not p.get("proceed"):
        return {"inject": False, "result": ""}
    intent = (p.get("intent") or "").strip()
    conf = float(p.get("confidence") or 0)
    if (not intent or intent == "default" or intent == "__none__" or conf < 0.5):
        return {"inject": False, "result": ""}
    hit = next((s for s in skills if s.get("name") == intent), None)
    if not hit or not (hit.get("description") or hit.get("when")):
        return {"inject": False, "result": ""}
    lines = [f"🎯 匹配技能：{hit['name']}（置信度 {conf:.2f}）",
             str(hit.get("description") or "")]
    if hit.get("when"):
        lines.append("适用时机：" + hit["when"])
    lines.append(f'→ 详细 SOP：read_skill("{hit["name"]}")；'
                 f'若需其常驻服务：skill_equip("{hit["name"]}") 后按返回清单调用。')
    return {"inject": True, "result": "\n".join(lines)}
